def squash(s: str) -> str:
    result = []
    i = 0
    n = len(s)

    while i < n:
        j = i + 1
        while j < n and s[j] == s[i]:
            j += 1

        char = s[i]
        escaped = "\\" + char if char == "\\" or "0" <= char <= "9" else char
        length = j - i

        if length >= 3:
            result.append(str(length) + escaped)
        else:
            result.append(escaped * length)

        i = j

    return "".join(result)
